class RecorderWorklet extends AudioWorkletProcessor {
  constructor() {
    super();
    // 增加单批分块大小至 8192 采样（约 180~500ms 一次），将跨线程与事件循环唤醒频率减少 75%，大幅削减 CPU 功耗
    this.BUFFER_SIZE = 8192;
    this.buffer = new Int16Array(this.BUFFER_SIZE);
    this.bufIndex = 0;
    this.isRecording = false;

    this.port.onmessage = (e) => {
      const data = e.data;
      if (data.cmd === 'start') {
        this.isRecording = true;
      } else if (data.cmd === 'pause') {
        this.isRecording = false;
        this.flush();
      } else if (data.cmd === 'resume') {
        this.isRecording = true;
      } else if (data.cmd === 'flush') {
        this.isRecording = false;
        this.flush();
        this.port.postMessage({ type: 'flushed' });
      }
    };
  }

  flush() {
    if (this.bufIndex > 0) {
      const slice = this.buffer.slice(0, this.bufIndex);
      this.port.postMessage({ type: 'data', buffer: slice.buffer }, [slice.buffer]);
      this.bufIndex = 0;
    }
  }

  process(inputs) {
    if (!this.isRecording) return true;
    const input = inputs[0];
    if (input && input.length > 0) {
      const channel = input[0];
      for (let i = 0; i < channel.length; i++) {
        let s = Math.max(-1, Math.min(1, channel[i]));
        this.buffer[this.bufIndex++] = s < 0 ? s * 0x8000 : s * 0x7FFF;

        if (this.bufIndex >= this.BUFFER_SIZE) {
          const copy = new Int16Array(this.buffer);
          this.port.postMessage({ type: 'data', buffer: copy.buffer }, [copy.buffer]);
          this.bufIndex = 0;
        }
      }
    }
    return true;
  }
}
